const $=id=>document.getElementById(id);
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
async function api(path,signal){const r=await fetch('/api/marketplace/'+path,{signal});if(!r.ok)throw Error('Request failed');const j=await r.json();if(!j.success)throw Error('Request failed');return j.data;}
const params=new URLSearchParams(location.search);let category=params.get('category')||(/^\/marketplace\/category\/([a-z0-9-]+)$/.exec(location.pathname)?.[1]||''),page=Math.max(1,parseInt(params.get('page'),10)||1),categories=[],controller;
$('search').value=params.get('search')||'';$('sort').value=params.get('sort')||'featured';for(const k of ['min','max'])if(params.has(k))$(k).value=Number(params.get(k))/100;if(params.has('days'))$('days').value=params.get('days');
function drawCategories(){const nav=$('categories');nav.replaceChildren();function button(name,slug){const b=el('button',name);b.type='button';b.setAttribute('aria-current',String(category===slug));b.onclick=()=>{category=slug;page=1;drawCategories();load()};return b}nav.append(button('All services',''));function branch(parent,target,seen){for(const c of categories.filter(x=>x.parent_id===parent)){if(seen.has(c.id))continue;const children=categories.some(x=>x.parent_id===c.id);const b=button(`${c.name} (${c.service_count})`,c.slug);if(children){const d=el('details');d.open=true;d.append(el('summary',c.name),b);branch(c.id,d,new Set([...seen,c.id]));target.append(d)}else target.append(b)}}branch(null,nav,new Set());}
function card(s){const a=el('a',undefined,'mp-card');a.href='/marketplace/service/'+encodeURIComponent(s.slug);const cover=el('div','LEAKENDIA','mp-cover');if(s.thumbnail_id){const img=el('img');img.src='/api/marketplace/media/'+encodeURIComponent(s.thumbnail_id);img.alt='';img.loading='lazy';img.onerror=()=>cover.replaceChildren(document.createTextNode('LEAKENDIA'));cover.replaceChildren(img)}const body=el('div',undefined,'mp-card-body');body.append(el('h3',s.title),el('p',s.summary||''));const bottom=el('div',undefined,'mp-card-bottom');bottom.append(el('span',s.price_minor==null?'Request pricing':'From '+new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(s.price_minor/100),'mp-price'),el('span','View service →'));body.append(bottom);a.append(cover,body);return a}
async function load(){if(!$('filters').reportValidity())return;if($('min').value!==''&&$('max').value!==''&&Number($('min').value)>Number($('max').value)){$('status').textContent='Minimum price must not exceed maximum price.';return}controller?.abort();controller=new AbortController();const signal=controller.signal;const q=new URLSearchParams({page:String(page),sort:$('sort').value||'featured'});if(category)q.set('category',category);if($('search').value.trim())q.set('search',$('search').value.trim());for(const k of ['min','max','days'])if($(k).value!=='')q.set(k,String(k==='days'?Number($(k).value):Math.round(Number($(k).value)*100)));history.replaceState(null,'','/marketplace?'+q);$('results-title').textContent=categories.find(c=>c.slug===category)?.name||'All services';$('status').textContent='Loading services…';$('cards').replaceChildren();$('pagination').hidden=true;try{const d=await api('services?'+q,signal);if(signal.aborted)return;$('cards').append(...d.items.map(card));$('status').textContent=d.items.length?`${d.items.length} services on this page`:'No published services match your selection.';$('pagination').hidden=page===1&&!d.hasMore;$('prev').disabled=page===1;$('next').disabled=!d.hasMore;$('page-number').textContent='Page '+page}catch(e){if(!signal.aborted)$('status').textContent='Unable to load services. Please try searching again.'}}
for(const id of ['mp-search','filters'])$(id).addEventListener('submit',e=>{e.preventDefault();page=1;load()});$('sort').onchange=()=>{page=1;load()};$('reset').onclick=()=>{category='';page=1;$('filters').reset();$('search').value='';$('sort').value='featured';drawCategories();load()};$('prev').onclick=()=>{page--;load()};$('next').onclick=()=>{page++;load()};api('categories').then(d=>{categories=d;drawCategories();$('results-title').textContent=categories.find(c=>c.slug===category)?.name||'All services'}).catch(()=>{$('categories').textContent='Categories unavailable.'});load();
